    protected updateBullet(t:number,b?:Bullet):void
    {
         //return;
         //log('update_test',this._testCount);
         /*
         if(this._testCount<=0)
         {
            return;
         }else{
             this._testCount--;
         }*/
         
         let changeflag:boolean=false;
 
         let right:number=1920;
         // var right:number=CoreRenderMode.RenderCore.app.renderer.width;
         
         //let left:number=0;
         let left:number=0;
         
         //let top:number=0;
         let top:number=1080;
         //top=b.gameBoundaryfoBullet.h;---要改這個20230816
         
         //let bottom:number=1080;
         let bottom:number=0;
 
         b.ePosition.x=b.position.x;
         
         b.ePosition.y=b.position.y;
         
         //let vxvalue:number=(b.isDrill)?600:1000;
         let vxvalue:number=1;
         
         /*
         b.position.x+=b.vx*t/vxvalue;
         
         b.position.y+=b.vy*t/vxvalue;
         */
         b.position.x+=b.vx*t/vxvalue;
         
         b.position.y+=b.vy*t/vxvalue;
 
 
         //log('update_checkBulletPosition',b.position.x,b.position.y);
 
         let contentSize:Size=b.bulletShell.getComponent(UITransform).contentSize;
 
         //--原本是依照左上角(0,0)坐標系去設計的判斷
         //--cocos是依照右下角(0,0)坐標系  
         //if(b.position.y<=top+b.bulletShell.height/2)
        if(b.position.y>=top+contentSize.height/2)
        {
             //--超出上面邊界
             b.vy*=-1;
             
             b.position.y=top+contentSize.height/2;
             
             changeflag=true;
         
         //}else if(b.position.y>=bottom-b.bulletShell.height/2){
        }else if(b.position.y<=bottom-contentSize.height/2)
        {
             //--超出下面邊界 
             b.vy*=-1;
             
             b.position.y=bottom-contentSize.height/2;
             
             changeflag=true;
     
        }
 
        if(b.position.x<=left+contentSize.width/2)
        {
             //--超出左邊邊界
             b.vx*=-1;
 
             b.position.x=left+contentSize.width/2;
             
             changeflag=true;
           
             
        }else if(b.position.x>=right-contentSize.width/2)
        {
             
             //--超出右邊邊界
             b.vx*=-1;
 
             b.position.x=right-contentSize.width/2;
 
             changeflag=true;
        } 
 
        //--測試關閉 20240227--(正式要打開) 
        b.bulletShell.setPosition(v3(b.position.x,b.position.y));

        //b.show.setPosition(v3(b.position.x,b.position.y));
        //--測試用的 20240227(正式關閉)
        
        //b.isDead=false;//--test
        //b.bulletShell.setPosition(v3(767.366699596394,1096.7060816812743));//--test
        //b.bulletShell.setPosition(v3((1920/2)+35,(1080/2)+35));//--test
        //b.show.setPosition(v3((1920/2)+35,(1080/2)+35));//--test
        
 
        if(!changeflag)
        {
            let theta:number=Math.atan2(b.position.y-b.ePosition.y,b.position.x-b.ePosition.x);
            
            b.bulletShell.angle=math.toDegree(theta);

            //b.show.angle=math.toDegree(theta);

        }
 
 
 
         //this.reNewBounding(b);--resetting collision boudary
 
         //--for test
         //-1396.4982652398392,103.51218719663106
         
        this.updateColliders(b,t);
 
    }
 
    protected updateColliders(b:Bullet,t:number):void
    {
        for(let i:number=0;i<b.collisions.length;i++)
        {
            
            //b.collisions[i].impl.update(t);
            
            (<BuiltinShape2D>b.collisions[i].impl).update();

        }
    }
  
